const createLoadout = (spec = {}) => createRawLoadout({ ...spec, modules: (spec.modules ?? []).map((entry) => ({ ...entry, x: entry.x == null ? entry.x : entry.x + 3, y: entry.y == null ? entry.y : entry.y + 3 })) });

const output = document.querySelector("#test-output"); const results = [];
function assert(condition, message) { if (!condition) throw new Error(message); }
function test(name, callback) { try { callback(); results.push(`PASS ${name}`); } catch (error) { results.push(`FAIL ${name}\n  ${error.message}`); } }

test("enemy base health values", () => { const hp = Object.fromEntries(ENEMY_CONFIG.map((enemy) => [enemy.type, enemy.hp])); assert(hp.scout === 5 && hp.swift === 5 && hp.guardian === 20, "enemy base health values are incorrect"); });
test("basic enemy shots fire straight downward", () => { const player = { x: 420, y: 700 }; const system = new WeaponSystem(); for (const type of ["scout", "swift", "guardian"]) { const definition = ENEMY_CONFIG.find((enemy) => enemy.type === type); const enemy = new Enemy(definition, 120, { spawnY: 100 }); const shot = system.fireEnemy(enemy, player); assert(!Array.isArray(shot) && Math.abs(shot.vx) < 0.001 && shot.vy > 0, `${type} did not fire straight downward`); } });
test("prototype enemy archive stays distinct and listed in the merged encyclopedia", () => { const ids = UNRELEASED_ENEMY_CONFIG.map((enemy) => enemy.id); const types = UNRELEASED_ENEMY_CONFIG.map((enemy) => enemy.type); const archive = getUnreleasedEnemyArchiveEntries(); const enemySection = getEncyclopediaSections().find((section) => section.title === "敌机档案"); const listedTitles = new Set(enemySection?.entries.map((entry) => entry.title) ?? []); const visualTypes = Object.fromEntries(archive.map((entry) => [entry.title, entry.enemyVisual.type])); const flippedNames = ["彗尾信使", "钟摆信标", "缎带鳐", "绽放的花蕾"]; assert(UNRELEASED_ENEMY_CONFIG.length === 10 && new Set(ids).size === 10 && new Set(types).size === 10, "unreleased enemy prototypes are incomplete or duplicated"); assert(UNRELEASED_ENEMY_CONFIG.every((enemy) => !ENEMY_CONFIG.includes(enemy) && getEnemyById(enemy.id) === null), "unreleased enemies leaked into active spawn definitions"); assert(visualTypes["彗尾信使"] === "comet" && visualTypes["钟摆信标"] === "pendulum" && visualTypes["缎带鳐"] === "ribbon" && visualTypes["绽放的花蕾"] === "petal", "unreleased enemy visual mapping is incorrect"); assert(flippedNames.every((name) => archive.find((entry) => entry.title === name)?.enemyVisual.flipY === true), "target enemy encyclopedia drawings are not vertically flipped"); assert(archive.length === 10 && archive.every((entry) => entry.enemyVisual && entry.description.length > 0 && listedTitles.has(entry.title)) && enemySection, "prototype enemies are missing from the merged encyclopedia archive"); });
test("100 level campaign and boss schedule", () => { assert(LEVELS.length === 100, "level count"); assert(Array.from({ length: 20 }, (_, index) => (index + 1) * 5).every((number) => LEVELS[number - 1].boss), "boss schedule"); assert(LEVELS[99].hpMultiplier > LEVELS[0].hpMultiplier && LEVELS[99].enemyPool.length > LEVELS[0].enemyPool.length, "difficulty did not grow"); const boss = createBossDefinition(100); const variantIds = ["storm-warden", "nest-matriarch", "prism-oracle", "zero-archon", "lattice-leviathan", "abyss-gardener", "chorus-conductor", "cryo-hive-queen"]; const variants = variantIds.map((id) => createBossDefinition(20, id)); assert(boss.boss && boss.hp > createBossDefinition(5).hp && boss.bossSkills.includes("radial"), "boss scaling"); assert(variants.every((item) => item.boss && item.bossShape && item.attackPattern) && new Set(variants.map((item) => item.bossShape)).size === variantIds.length && new Set(variants.map((item) => item.attackPattern)).size >= 5, "boss variants are not visually or mechanically distinct"); });
test("encyclopedia lists every boss variant", () => { const bossSection = getEncyclopediaSections().find((section) => section.title === "首领机制"); const titles = bossSection.entries.map((entry) => entry.title); assert(["雷暴监守", "覆巢母舰", "棱镜先知", "零度执政官", "晶格利维坦", "深渊园丁", "合唱指挥舰", "寒潮蜂后"].every((name) => titles.includes(name)), "boss variant encyclopedia entries are incomplete"); });
test("beyond event archive provides rare legendary encounters", () => { const system = new BeyondLightConeSystem(); const run = system.createRun(1, "event-test-seed"); const node = { id: "event-test", type: "event" }; const ids = BEYOND_EVENTS.map((event) => event.id); assert(BEYOND_EVENTS.length === 34 && new Set(ids).size === 34 && BEYOND_EVENTS.filter((event) => event.rareLegendary).length === 4 && BEYOND_EVENTS.every((event) => event.choices.length >= 2), "event archive is incomplete"); const encounter = system.createEventEncounter(run, node); const selectedChoice = encounter.choices.find((choice) => choice.available); const result = system.resolveEventChoice(run, node, encounter.event.id, selectedChoice?.id); assert(run.eventHistory.includes(encounter.event.id) && !run.activeEvent && result.event.id === encounter.event.id, "event result did not persist correctly"); });
test("dormant fusion definitions keep exact recipes without exposing disabled modules", () => { const system = new BeyondLightConeSystem(); const run = system.createRun(1, "fusion-test-seed"); run.inventory["weapon-water-shot"] = 1; run.inventory["weapon-ball-lightning"] = 1; run.inventory["weapon-flame-crossbow"] = 1; const slots = Array(9).fill(null); slots[3] = "weapon-water-shot"; slots[4] = "weapon-ball-lightning"; slots[5] = "weapon-flame-crossbow"; const product = system.synthesize(run, slots).product; assert(product.id === "fusion-cryo-hive" && run.inventory[product.id] === 1, "translated fusion recipe did not resolve"); const returned = system.decompose(run, product.id); assert(returned.returned.length === 3 && run.inventory[product.id] === 0 && run.inventory["weapon-water-shot"] === 1, "fusion decomposition did not restore materials"); assert(system.getBeyondRewardModules().every((module) => !PLAYER_DISABLED_MODULE_IDS.has(module.id)), "disabled modules leaked into the reward pool"); const bossNode = run.map.at(-1)[0]; const bossReward = system.rewardModules(run, 1, { boss: true }); assert(bossReward.length === 1 && getModuleById(bossReward[0])?.rarity === "legendary" && bossReward[0] === bossNode.bossRewardId, "boss did not grant its fixed legendary module"); });
test("beyond chapter flow keeps resources and scales later chapters", () => { const system = new BeyondLightConeSystem(); assert(getBeyondChapterCount(1) === 1 && getBeyondChapterCount(2) === 2 && getBeyondChapterCount(3) === 3 && getBeyondChapterCount(4) === 3, "chapter counts are incorrect"); const run = system.createRun(3, "chapter-test-seed"); run.inventory["weapon-nest"] = 2; run.gold = 77; run.hp = 41; const firstMapSeed = run.chapterSeed; const firstBoss = run.map.at(-1)[0]; const firstConfig = system.getBattleConfig(run, firstBoss); assert(run.chapter === 1 && run.totalChapters === 3, "multi-chapter run did not initialize"); assert(system.advanceChapter(run) && run.chapter === 2 && run.currentNodeId === null && run.visited.length === 0, "chapter did not advance"); const secondConfig = system.getBattleConfig(run, run.map.at(-1)[0]); assert(run.chapterSeed !== firstMapSeed && run.inventory["weapon-nest"] === 2 && run.gold === 77 && run.hp === 41 && secondConfig.hpMultiplier > firstConfig.hpMultiplier, "chapter transition lost resources or did not scale difficulty"); });
test("beyond first chapter opens with three mandatory event nodes", () => { const system = new BeyondLightConeSystem(); const run = system.createRun(1, "opening-event-seed"); const opening = run.map.slice(0, 3).map((layer) => layer[0]); assert(opening.length === 3 && run.map.slice(0, 3).every((layer) => layer.length === 1) && opening.every((node) => node.type === "event") && opening.map((node) => node.eventId).join(",") === "orphan-wingman,zero-maintenance,gravity-post", "opening route is not three sequential events"); let available = system.getAvailableNodes(run); for (const node of opening) { assert(available.length === 1 && available[0].id === node.id, "opening event is not mandatory"); system.enterNode(run, node.id); available = system.getAvailableNodes(run); } assert(available.length > 0 && available.every((node) => node.layer === 3), "normal route did not begin after the third event"); });
test("special environments unlock after level 25", () => { assert(LEVELS[24].environmentPool.length === 0 && !LEVELS[24].environment, "environment unlocked too early"); assert(LEVELS[25].environmentPool.length > 0 && LEVELS[25].environment, "environment missing from level 26"); assert(getEnvironmentPool(50).length >= 4, "late environments missing"); });
test("dodge mode difficulty and hazard generation", () => { assert(DODGE_DIFFICULTIES.length === 3 && getDodgeDifficulty("nightmare").speed > getDodgeDifficulty("easy").speed, "dodge difficulties are incomplete"); const game = Object.create(Game.prototype); game.bounds = { width: 480, height: 854 }; game.dodgeDifficulty = getDodgeDifficulty("hard"); game.elapsed = 0; game.dodgePatternIndex = 0; game.projectiles = []; game.spawnDodgePattern(); assert(game.projectiles.length > 0 && game.projectiles.every((projectile) => projectile.team === "enemy" && projectile.dodgeBullet), "dodge mode did not create hazard projectiles"); });

test("dodge mode can spawn hazards in the lower half", () => { const game = Object.create(Game.prototype); game.bounds = { width: 480, height: 854 }; game.dodgeDifficulty = { ...getDodgeDifficulty("easy"), patternPool: [10] }; game.elapsed = 0; game.dodgePatternIndex = 0; game.dodgePatternHistory = -1; game.projectiles = []; game.spawnDodgePattern(); assert(game.projectiles.length > 0 && game.projectiles.some((projectile) => projectile.y > game.bounds.height * 0.5 && projectile.vy < 0), "dodge mode lower-half pattern is missing"); });
test("boss summon configuration and wave", () => { const boss = createBossDefinition(25); assert(boss.summon.interval < createBossDefinition(5).summon.interval && boss.summon.count === 2, "boss summon scaling"); const game = Object.create(Game.prototype); game.boss = { x: 240, y: 120, hp: 100, definition: boss }; game.bossSummonTimer = 0; game.bossSummonCount = 0; game.enemies = [game.boss]; game.levelNumber = 25; game.levelConfig = { hpMultiplier: 1.5, speedMultiplier: 1.2 }; game.bounds = { width: 480, height: 854 }; const minions = game.updateBossSummons(0.1); assert(minions.length === 2 && minions.every((enemy) => enemy.summoned && !enemy.boss), "boss did not summon minions"); game.enemies.push(...minions); game.bossSummonTimer = 0; assert(game.updateBossSummons(0.1).length === 2, "boss summon cooldown or cap incorrect"); });
test("skill modules keep nine-module limit while regular total limit is removed", () => { const modules = [{ moduleId: "special-chainsaw", x: 4, y: 3 }, { moduleId: "special-chainsaw", x: 2, y: 3 }, { moduleId: "special-chainsaw", x: 0, y: 3 }, { moduleId: "special-chainsaw", x: -2, y: 3 }, { moduleId: "special-chainsaw", x: 6, y: 3 }, { moduleId: "special-chainsaw", x: 8, y: 3 }, { moduleId: "special-chainsaw", x: 10, y: 3 }, { moduleId: "special-chainsaw", x: 4, y: 5 }, { moduleId: "special-chainsaw", x: 2, y: 5 }, { moduleId: "special-chainsaw", x: 0, y: 5 }]; const manySkills = createLoadout({ modules }); assert(MAX_SKILL_MODULES === 9 && countSkillModules(manySkills) === 10 && !validateLoadout(manySkills).valid, "tenth skill module should be rejected"); });

test("15x15 board and centered core", () => { assert(ASSEMBLY_BOARD.columns === 15 && ASSEMBLY_BOARD.rows === 15, "board size"); assert(ASSEMBLY_BOARD.corePosition.x === 7 && ASSEMBLY_BOARD.corePosition.y === 7 && CORE_MODULE.type === "core", "core position"); });
test("large regular loadout remains valid", () => { const modules = []; for (let y = 0; y < ASSEMBLY_BOARD.rows && modules.length < 120; y += 1) for (let x = 0; x < ASSEMBLY_BOARD.columns && modules.length < 120; x += 1) if (x !== ASSEMBLY_BOARD.corePosition.x || y !== ASSEMBLY_BOARD.corePosition.y) modules.push({ moduleId: "weapon-ricochet", x, y }); const loadout = createRawLoadout({ modules }); const result = validateLoadout(loadout); assert(result.valid && loadout.modules.length === 120, `large loadout rejected: ${result.reason}`); });
test("large regular loadout initializes combat entities", () => { const modules = []; for (let y = 0; y < ASSEMBLY_BOARD.rows && modules.length < 120; y += 1) for (let x = 0; x < ASSEMBLY_BOARD.columns && modules.length < 120; x += 1) if (x !== ASSEMBLY_BOARD.corePosition.x || y !== ASSEMBLY_BOARD.corePosition.y) modules.push({ moduleId: "weapon-ricochet", x, y }); const loadout = createRawLoadout({ modules }); const player = new Player({ x: 240, y: 700, stats: calculateFinalStats(PLAYER_BASE_STATS, getInstalledEntries(loadout).map(({ module }) => module)), loadout }); const shots = new WeaponSystem().firePlayer(player, []); assert(player.installedEntries.length === 121 && shots.length > 0 && player.weaponEntries.length === 120, "large loadout combat initialization failed"); });
test("multi-cell electric whirlwind loadout", () => { const loadout = createLoadout({ modules: [{ moduleId: "weapon-nest", x: 1, y: 4 }, { moduleId: "weapon-electric-whirlwind", x: 3, y: 3 }] }); assert(validateLoadout(loadout).valid, "connected loadout"); const cells = getModuleById("weapon-electric-whirlwind").footprint.cells; assert(cells.length === 3 && cells.every(([x]) => x === 0), "vertical three-cell footprint"); });
test("stats merge", () => { const loadout = createLoadout({ modules: [{ moduleId: "weapon-nest", x: 4, y: 3 }, { moduleId: "special-wingman", x: 3, y: 4 }] }); const stats = calculateFinalStats(PLAYER_BASE_STATS, getInstalledEntries(loadout).map(({ module }) => module)); assert(stats.maxHp === PLAYER_BASE_STATS.maxHp && stats.moveSpeed === PLAYER_BASE_STATS.moveSpeed && stats.attackSpeed === PLAYER_BASE_STATS.attackSpeed, "base stats changed"); });
test("wolfpack synergy validates exclusive module pairing", () => {
  const base = createLoadout({ modules: [{ moduleId: "weapon-nest", x: 4, y: 3 }, { moduleId: "special-wingman", x: 4, y: 2 }] });
  const [nest, wingman] = base.modules;
  const selected = { ...base, synergies: [{ id: "synergy-wolfpack", moduleInstanceIds: [nest.instanceId, wingman.instanceId] }] };
  const duplicated = { ...selected, synergies: [...selected.synergies, { id: "synergy-wolfpack", moduleInstanceIds: [nest.instanceId, wingman.instanceId] }] };
  assert(validateLoadout(selected).valid && hasActiveSynergy(selected, "synergy-wolfpack"), "wolfpack selection is invalid");
  assert(normalizeSynergies(duplicated).length === 1 && getSynergyStates(selected)[0].activeSelections.length === 1, "occupied modules were reused by another synergy");
});
test("wolfpack wingman keeps its bolt and adds nest volley", () => {
  const wingman = new Wingman({ x: 240, y: 700, stats: { attackSpeed: 1 } }, { wolfpack: true }); wingman.nestTimer = 0;
  const system = new WeaponSystem(); const bolt = wingman.fire(); const volley = system.fireWingmanNest(wingman, [{ id: "target", x: 240, y: 280, hp: 10 }]);
  assert(bolt?.kind === "bolt" && volley.length === 6 && volley.every((shot) => shot.kind === "nestMissile" && shot.damage === 5), "wolfpack did not add an independent nest volley");
});
test("water-fire synergy swaps attacks with the requested probabilities", () => {
  const loadout = createLoadout({ modules: [{ instanceId: "flame-1", moduleId: "weapon-flame-crossbow", x: 7, y: 6 }, { instanceId: "water-1", moduleId: "weapon-water-shot", x: 6, y: 7 }], synergies: [{ id: "synergy-water-fire", moduleInstanceIds: ["water-1", "flame-1"] }] });
  assert(hasActiveSynergy(loadout, "synergy-water-fire"), "water-fire synergy is not active");
  const player = new Player({ x: 240, y: 700, stats: calculateFinalStats(PLAYER_BASE_STATS, getInstalledEntries(loadout).map(({ module }) => module)), loadout });
  const originalRandom = Math.random;
  try {
    player.weaponTimers.forEach((_, key) => player.weaponTimers.set(key, 0));
    let rolls = [0.2, 0.9]; Math.random = () => rolls.shift() ?? 0.9;
    const waterSwap = new WeaponSystem().firePlayer(player, []);
    assert(waterSwap.filter((shot) => shot.kind === "waterShot").length === 4 && waterSwap.every((shot) => shot.element === "water"), "flame attack did not convert to three water shots");
    player.weaponTimers.forEach((_, key) => player.weaponTimers.set(key, 0));
    rolls = [0.9, 0.2];
    const fireSwap = new WeaponSystem().firePlayer(player, []);
    assert(fireSwap.filter((shot) => shot.kind === "flameArrow").length === 3 && fireSwap.filter((shot) => shot.kind === "waterShot" && shot.element === "fire").length === 1 && fireSwap.some((shot) => shot.kind === "waterShot" && shot.burn?.ticks === 9 && shot.color === "#ff3344"), "water attack did not convert to a red burning water shot");
  } finally { Math.random = originalRandom; }
});
test("white hole takes over captured bullets and caps healing", () => {
  const game = Object.create(Game.prototype); const player = { x: 240, y: 700 }; game.player = player; game.projectiles = []; game.whiteHoleActive = true;
  const hole = new Projectile({ x: 240, y: 400, damage: 0, radius: 8, color: "#b57bff", life: 2, team: "player", kind: "blackHole", blackHole: { capturedProjectiles: new Set() } });
  const captured = new Projectile({ x: 250, y: 400, vx: 0, vy: 0, damage: 7, radius: 5, color: "#ff557c", life: 3, team: "enemy" });
  captured.blackHoleCapturedBy = hole; hole.blackHole.capturedProjectiles.add(captured); game.projectiles = [hole, captured];
  game.startPolarityReverse(0.25); assert(!captured.blackHoleCapturedBy && captured.whiteHoleCandidate && captured.polarityDelay === 0.25, "captured bullet was not released");
  captured.polarityDelay = 0; game.convertPolarityProjectile(captured); assert(captured.team === "player" && captured.homingPlayer && captured.pierce && captured.whiteHoleHealState.remaining === 30, "white hole projectile conversion failed");
  const target = { id: "white-hole-target", x: captured.x, y: captured.y, radius: 8, hp: 20, definition: { score: 1 }, takeDamage(amount) { this.hp -= amount; return false; } };
  const hit = new CollisionSystem().resolve({ player: { x: 0, y: 0, radius: 10 }, enemies: [target], projectiles: [captured] }); assert(target.hp === 13 && !hit.removedProjectiles.has(captured), "white hole bullet did not pierce enemy");
  captured.x = 0; captured.y = 0; const heal = new CollisionSystem().resolve({ player: { x: 0, y: 0, radius: 10 }, enemies: [], projectiles: [captured] }); assert(heal.playerHealing === 7 && heal.playerDamage === 0, "white hole bullet did not heal player");
});
test("energy aggregator adds attack speed and is an automatic module", () => { const aggregator = getModuleById("special-energy-aggregator"); const boosted = calculateFinalStats(PLAYER_BASE_STATS, [aggregator, aggregator]); const capped = calculateFinalStats(PLAYER_BASE_STATS, Array.from({ length: 12 }, () => aggregator)); assert(MODULE_CONFIG.weapons.includes(aggregator) && !MODULE_CONFIG.specials.includes(aggregator) && aggregator.type === "weapon" && !aggregator.skill && aggregator.footprint.cells.length === 1 && aggregator.shareCode === 12, "aggregator category configuration missing"); assert(boosted.attackSpeed === 1.4 && capped.attackSpeed === GAME_CONFIG.player.maxAttackSpeed, `invalid attack speed: ${boosted.attackSpeed}/${capped.attackSpeed}`); });
