test("loadout code round trip", () => { const source = createLoadout({ modules: [{ moduleId: "weapon-electric-whirlwind", x: 3, y: 3 }, { moduleId: "special-optical", x: 5, y: 4, rotation: 1 }] }); const code = encodeLoadoutCode(source); const restored = decodeLoadoutCode(code).loadout; const signature = (loadout) => loadout.modules.map(({ moduleId, x, y, rotation }) => `${moduleId}:${x}:${y}:${rotation}`).sort().join("|"); assert(code.startsWith("!1") && !code.includes("weapon") && !code.includes("special"), "code exposes module ids"); assert(signature(restored) === signature(source), "loadout was not restored exactly"); });
test("loadout code validates checksum and module codes", () => { const codes = [...MODULE_CONFIG.weapons, ...MODULE_CONFIG.specials].map((module) => module.shareCode); assert(new Set(codes).size === codes.length && codes.every((code) => Number.isInteger(code) && code > 0), "module share codes are not stable and unique"); const code = encodeLoadoutCode(createLoadout({ modules: [{ moduleId: "weapon-electric-whirlwind", x: 3, y: 3 }] })); const last = code.at(-1); const corrupted = `${code.slice(0, -1)}${last === "0" ? "1" : "0"}`; let rejected = false; try { decodeLoadoutCode(corrupted); } catch { rejected = true; } assert(rejected, "corrupted code was accepted"); });
test("player invulnerability after damage", () => { const player = new Player({ x: 240, y: 700, stats: PLAYER_BASE_STATS, loadout: createLoadout({ modules: [] }) }); player.damage(5); assert(player.hp === 95 && player.invulnerabilityTimer === 1, "first damage was not applied"); player.damage(5); assert(player.hp === 95, "damage applied during invulnerability"); player.update(1.01, { pointer: { active: false }, getMovementVector: () => ({ x: 0, y: 0 }) }, GAME_CONFIG.canvas); player.damage(5); assert(player.hp === 90 && player.invulnerabilityTimer === 1, "damage did not return after invulnerability"); });
test("current weapon configuration", () => { assert(MODULE_CONFIG.weapons.length === 14 && ["weapon-obsidian-beam", "weapon-eclipse-pulse", "weapon-fire-feather", "fusion-polar-saw"].every((id) => MODULE_CONFIG.weapons.some((module) => module.id === id)), "current weapon count or v0.7 entries"); assert(["weapon-single", "weapon-twin", "weapon-spread", "weapon-missile", "weapon-boomerang"].every((id) => !getModuleById(id)), "removed weapon modules remain"); const nest = getModuleById("weapon-nest"); assert(nest.behavior.projectile.color === "#ef294d" && nest.behavior.projectile.speed === 580 && nest.behavior.projectile.radius === 18 && nest.behavior.projectile.explosionRadius === 72 && nest.behavior.projectile.homingDelay === 0.42 && nest.behavior.spreadAngle === 0.18, "nest tuning"); assert(getModuleById("weapon-ball-lightning").behavior.projectile.radius === 12 && getModuleById("weapon-ball-lightning").behavior.projectile.growthRate === 8.8, "ball lightning size"); const whirlwind = getModuleById("weapon-electric-whirlwind"); assert(whirlwind.footprint.cells.length === 3 && whirlwind.footprint.cells.every(([x]) => x === 0) && whirlwind.behavior.projectile.damage === 2 && whirlwind.behavior.projectile.radius === 76 && whirlwind.behavior.projectile.speed === 520 && whirlwind.behavior.projectile.returnTimeout === 3 && whirlwind.behavior.projectile.emergencyReturnSpeed === 1800 && whirlwind.behavior.projectile.rearmDelay === 0.6 && whirlwind.behavior.damageInterval === 0.1, "whirlwind tuning"); const lightning = getModuleById("weapon-lightning-generator"); assert(lightning.footprint.cells.length === 2 && lightning.behavior.fireRate === 0.5 && lightning.behavior.fireInterval === 2 && lightning.behavior.projectile.damage === 7 && lightning.behavior.projectile.chainRadius === 200 && lightning.behavior.projectile.chainLife === 0.25 && lightning.behavior.projectile.flashDuration === 0.045, "lightning generator tuning"); const flame = getModuleById("weapon-flame-crossbow"); assert(flame.rarity === "epic" && flame.element === "fire" && flame.behavior.fireInterval === 1.5 && flame.behavior.angles.length === 3 && flame.behavior.projectile.damage === 5 && flame.behavior.projectile.burn.duration === 3 && flame.behavior.projectile.burn.tickInterval === 1 / 3 && flame.behavior.projectile.burn.ticks === 9, "flame crossbow configuration"); const water = getModuleById("weapon-water-shot"); assert(water.rarity === "epic" && water.element === "water" && water.behavior.fireRate === 5 && water.behavior.projectile.explosionDamage === 2 && water.behavior.projectile.explosionRadius > 0, "water shot configuration"); });
test("updated special module footprints", () => { const zero = getModuleById("special-zero"); const wingman = getModuleById("special-wingman"); assert(zero.footprint.cells.length === 3 && zero.footprint.cells.every(([, y]) => y === 0), "zero domain is horizontal three-cell"); assert(wingman.footprint.cells.length === 3 && wingman.footprint.cells.every(([, y]) => y === 0), "wingman is horizontal three-cell"); });

test("nest missiles spread before homing", () => { const player = { x: 240, y: 700, loadout: createLoadout({ modules: [{ moduleId: "weapon-nest", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {} }; const makeEnemy = (id, x) => ({ id, x, y: 240, hp: 10 }); const enemies = [makeEnemy("left", 80), makeEnemy("mid", 240), makeEnemy("right", 400)]; const missiles = new WeaponSystem().firePlayer(player, enemies); assert(new Set(missiles.map((missile) => missile.target?.id)).size === 3, "nest targets are not distributed"); const initialVx = missiles.map((missile) => missile.vx); missiles[0].update(0.2, enemies); assert(missiles[0].vx === initialVx[0], "nest homed before spread delay"); missiles[0].update(0.3, enemies); assert(missiles[0].vx !== initialVx[0], "nest did not start homing after delay"); });
test("nest missile creates visible explosion event", () => { const player = { x: 240, y: 700, loadout: createLoadout({ modules: [{ moduleId: "weapon-nest", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {} }; const projectile = new WeaponSystem().firePlayer(player, [])[0]; const enemy = { id: "target", x: projectile.x, y: projectile.y, radius: 10, hp: 10, definition: { score: 1 }, takeDamage(amount) { this.hp -= amount; return this.hp <= 0; } }; const result = new CollisionSystem().resolve({ player, enemies: [enemy], projectiles: [projectile] }); assert(projectile.kind === "nestMissile" && Math.abs(Math.hypot(projectile.vx, projectile.vy) - 580) < 0.001 && result.explosionEvents.length === 1 && result.explosionEvents[0].radius === 72, `nest explosion event missing: kind=${projectile.kind}, speed=${Math.hypot(projectile.vx, projectile.vy)}, radius=${projectile.explosionRadius}, events=${result.explosionEvents.length}`); });
test("lightning generator chains unique nearby targets", () => { const player = { x: 240, y: 700, loadout: createLoadout({ modules: [{ moduleId: "weapon-lightning-generator", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {} }; const makeEnemy = (id, x, y) => ({ id, x, y, radius: 8, hp: 10, definition: { score: 1 }, takeDamage(amount) { this.hp -= amount; return this.hp <= 0; } }); const enemies = [makeEnemy("front", 240, 500), makeEnemy("near", 240, 570), makeEnemy("far", 400, 570), makeEnemy("offscreen", 500, 570), makeEnemy("back", 240, 820)]; const projectile = new WeaponSystem().firePlayer(player, enemies)[0]; assert(projectile.kind === "chainLightning" && projectile.target.id === "near" && projectile.chainRadius === 200 && projectile.life === 0.25, "lightning target or lifetime incorrect"); const result = new CollisionSystem().resolve({ player, enemies, projectiles: [projectile] }); assert(result.damageEvents.length === 3 && enemies.filter((enemy) => enemy.hp === 3).length === 3 && enemies[3].hp === 10 && enemies[4].hp === 10, "lightning chain did not hit only visible unique targets"); });
test("weapon origin follows module", () => { const loadout = createLoadout({ modules: [{ moduleId: "weapon-ricochet", x: 5, y: 4 }] }); const player = { x: 100, y: 200, loadout, canFireWeapon: () => true, armWeapon: () => {} }; const projectile = new WeaponSystem().firePlayer(player, [])[0]; assert(projectile.x === 113 && projectile.y === 192, "origin incorrect"); });
test("electric whirlwind returns and deals area damage", () => { const player = { x: 100, y: 300, loadout: createLoadout({ modules: [{ moduleId: "weapon-electric-whirlwind", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {} }; const projectile = new WeaponSystem().firePlayer(player, [])[0]; assert(projectile.kind === "electricWhirlwind" && projectile.whirlwind && projectile.vy < 0, "whirlwind did not launch upward"); projectile.y = 20; projectile.update(0.01, []); assert(projectile.phase === 1, "whirlwind did not turn at top"); const enemy = { id: "near", x: projectile.x + 15, y: projectile.y, radius: 8, hp: 12, definition: { score: 1 }, takeDamage(amount) { this.hp -= amount; return this.hp <= 0; } }; projectile.whirlwind.damageTimer = 0; const result = new CollisionSystem().resolve({ player, enemies: [enemy], projectiles: [projectile] }); assert(enemy.hp === 10 && result.damageEvents.length === 1, "whirlwind area damage failed"); });
test("ion saw uses a wide dual-side high-frequency damage zone", () => { const player = { x: 240, y: 700, radius: 12 }; const makeEnemy = (id, x, y) => ({ id, x, y, radius: 8, hp: 20, definition: { score: 1 }, takeDamage(amount) { this.hp -= amount; return this.hp <= 0; } }); const left = makeEnemy("left", 198, 700); const right = makeEnemy("right", 282, 700); const outside = makeEnemy("outside", 240, 660); const ionSaw = { active: true, damage: 2, damageTimer: 0, damageInterval: 0.12, reach: 42, radius: 26 }; const first = new CollisionSystem().resolve({ player, enemies: [left, right, outside], projectiles: [], ionSaw }); assert(first.sawTriggered && first.sawHitCount === 2 && left.hp === 18 && right.hp === 18 && outside.hp === 20 && first.destroyedEnemies.size === 0, "ion saw did not apply normal dual-side damage"); ionSaw.damageTimer = ionSaw.damageInterval; const second = new CollisionSystem().resolve({ player, enemies: [left, right, outside], projectiles: [], ionSaw }); assert(second.sawHitCount === 0 && left.hp === 18 && right.hp === 18, "ion saw ignored its damage interval"); });
test("ion saw cuts enemy projectiles", () => { const player = { x: 240, y: 700, radius: 12 }; const makeProjectile = (x, y) => new Projectile({ x, y, vx: 0, vy: 100, damage: 5, radius: 5, color: "#ff638c", life: 2, team: "enemy", kind: "enemyBolt" }); const left = makeProjectile(198, 700); const right = makeProjectile(282, 700); const outside = makeProjectile(240, 660); const ionSaw = { active: true, damage: 2, damageTimer: 0, damageInterval: 0.12, reach: 42, radius: 26 }; const result = new CollisionSystem().resolve({ player, enemies: [], projectiles: [left, right, outside], ionSaw }); assert(result.sawTriggered && result.sawProjectileCount === 2 && result.removedProjectiles.has(left) && result.removedProjectiles.has(right) && !result.removedProjectiles.has(outside), "ion saw did not cut enemy projectiles"); });
test("electric whirlwind aims and rearms after return", () => { const player = { x: 240, y: 700, loadout: createLoadout({ modules: [{ moduleId: "weapon-electric-whirlwind", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {}, activeWhirlwinds: new Map(), whirlwindCooldowns: new Map(), canFireWhirlwind(slotId) { return (this.whirlwindCooldowns.get(slotId) ?? 0) <= 0; } }; const enemy = { id: "right", x: 400, y: 450, hp: 10 }; const system = new WeaponSystem(); const projectile = system.firePlayer(player, [enemy])[0]; const slotId = [...player.activeWhirlwinds.keys()][0]; assert(projectile.vx > 0 && projectile.vy < 0, "whirlwind did not aim at nearest enemy"); projectile.x = 470; projectile.y = 300; projectile.update(0.01, [enemy], { width: 480, height: 854 }); assert(projectile.phase === 1, "whirlwind did not return from screen edge"); projectile.whirlwind.returnAge = 3.01; projectile.update(0.01, [enemy], { width: 480, height: 854 }); assert(Math.abs(Math.hypot(projectile.vx, projectile.vy) - 1800) < 0.001, "emergency return speed missing"); projectile.x = player.x; projectile.y = player.y - 24; projectile.update(0.01, [enemy], { width: 480, height: 854 }); assert(player.whirlwindCooldowns.get(slotId) === 0.6, "rearm delay missing"); });
test("skill cooldown ignores attack speed", () => { const loadout = createLoadout({ modules: [{ moduleId: "weapon-nest", x: 4, y: 3 }, { moduleId: "special-optical", x: 5, y: 3 }, { moduleId: "special-energy-aggregator", x: 3, y: 4 }] }); const skills = new SkillSystem(loadout); const game = { state: "playing", createDecoy: (duration) => { game.duration = duration; }, player: { stats: { attackSpeed: 3 } } }; assert(skills.activate(0, game) && game.duration === 5 && skills.getState()[0].cooldownRemaining === 20 && !skills.activate(0, game), "skill cooldown was altered by attack speed"); });
test("ion saw skill keeps its own display name", () => { const loadout = createLoadout({ modules: [{ moduleId: "special-chainsaw", x: 4, y: 3 }] }); const skill = new SkillSystem(loadout).getState()[0]; assert(skill.id === "ionSaw" && skill.name === "离子链锯", "ion saw skill name was replaced"); });
test("multiple sonic skills stay independent", () => { const loadout = createLoadout({ modules: [{ moduleId: "special-sonic", x: 4, y: 3 }, { moduleId: "special-sonic", x: 4, y: 5 }] }); const skills = new SkillSystem(loadout); const game = { state: "playing", waveCalls: [], startSonicWave: (duration) => game.waveCalls.push(duration) }; assert(skills.getState().length === 2, "duplicate sonic skills were not preserved"); assert(skills.activate(0, game) && skills.activate(1, game), "sonic skills cannot be activated independently"); assert(game.waveCalls.length === 2 && !skills.activate(0, game) && !skills.activate(1, game), "sonic skill cooldowns are shared"); });
test("sonic wave interval and top cleanup", () => { const game = Object.create(Game.prototype); game.elapsed = 0; game.sonicWaves = [{ spawnTimer: 0, nextY: 0, step: 38 }]; game.lasers = []; game.updateSonicWave(0.01); assert(SONIC_WAVE_CONFIG.spawnInterval === 0.15, "sonic interval is not 0.15 seconds"); assert(game.sonicWaves.length === 0 && game.lasers.length === 1, "top beam sequence did not finish cleanly"); game.updateSonicWave(SONIC_WAVE_CONFIG.beamLife); assert(game.lasers.length === 1 && game.lasers[0].life === 0, "beam damage lifetime was not separated from visual afterglow"); game.updateSonicWave(SONIC_WAVE_CONFIG.beamVisualLife); assert(game.lasers.length === 0, "top beam visual afterglow was not removed"); });
test("abyss bloom fires petals in all four directions", () => { const game = Object.create(Game.prototype); game.player = { x: 240, y: 400 }; game.enemies = []; game.projectiles = []; game.skyProtocols = []; game.azureSingularities = []; game.starRings = []; game.cryoHives = []; game.abyssBlooms = [{ duration: 2, pulse: 0, fireTimer: 0, moduleInstanceId: null }]; game.updateFusionSkills(0.01); assert(game.projectiles.length === 4 && game.projectiles.every((projectile) => projectile.kind === "abyssPetal" && projectile.team === "player"), "abyss bloom did not fire four petals"); const directions = game.projectiles.map((projectile) => Math.round(Math.atan2(projectile.vy, projectile.vx) * 100) / 100); assert(new Set(directions).size === 4, "abyss bloom petals did not cover four directions"); });
test("abyss bloom fires 150 percent faster", () => { const game = Object.create(Game.prototype); game.player = { x: 240, y: 400 }; game.enemies = []; game.projectiles = []; game.skyProtocols = []; game.azureSingularities = []; game.starRings = []; game.cryoHives = []; game.abyssBlooms = [{ duration: 2, pulse: 0, fireTimer: 0, moduleInstanceId: null }]; game.updateFusionSkills(0.01); game.updateFusionSkills(0.184); assert(game.projectiles.length === 8, "abyss bloom fire interval was not reduced by 150 percent frequency increase"); });
test("multiple abyss blooms remain independent", () => { const game = Object.create(Game.prototype); game.player = { x: 240, y: 400 }; game.enemies = []; game.projectiles = []; game.skyProtocols = []; game.azureSingularities = []; game.starRings = []; game.cryoHives = []; game.abyssBlooms = []; game.startAbyssBloom(2, "abyss-left"); game.startAbyssBloom(2, "abyss-right"); assert(game.abyssBlooms.length === 2, "multiple abyss bloom activations were collapsed"); game.updateFusionSkills(0.01); assert(game.projectiles.length === 8 && game.abyssBlooms.length === 2, "multiple abyss blooms did not fire independently"); });
test("fusion summons orbit their installed module origins", () => { const abyss = getModuleById("fusion-abyss-bloom"); const cryo = getModuleById("fusion-cryo-hive"); const game = Object.create(Game.prototype); game.player = { x: 240, y: 400, loadout: { corePosition: { x: 7, y: 7 } }, installedEntries: [{ instanceId: "abyss", x: 8, y: 7, module: abyss }, { instanceId: "cryo", x: 7, y: 8, module: cryo }] }; const abyssOrigin = game.getFusionSkillOrigin("abyss", "abyssBloom"); const cryoOrigin = game.getFusionSkillOrigin("cryo", "cryoHive"); assert(abyssOrigin.x !== game.player.x || abyssOrigin.y !== game.player.y, "abyss bloom still uses core origin"); assert(cryoOrigin.x !== game.player.x || cryoOrigin.y !== game.player.y, "cryo hive still uses core origin"); });
test("duplicate fusion modules keep their own origins", () => { const abyss = getModuleById("fusion-abyss-bloom"); const game = Object.create(Game.prototype); game.player = { x: 240, y: 400, loadout: { corePosition: { x: 7, y: 7 } }, installedEntries: [{ instanceId: "abyss-left", x: 6, y: 7, module: abyss }, { instanceId: "abyss-right", x: 8, y: 7, module: abyss }] }; const left = game.getFusionSkillOrigin("abyss-left", "abyssBloom"); const right = game.getFusionSkillOrigin("abyss-right", "abyssBloom"); assert(left.x < game.player.x && right.x > game.player.x && left.x !== right.x, "duplicate abyss blooms share one module origin"); });
test("ice shard applies a refreshing behavior slow", () => { const definition = { id: "test-slow", type: "striker", hp: 100, speed: 100, radius: 8, score: 1, shootInterval: 2 }; const enemy = new Enemy(definition, 100, { spawnY: 0 }); enemy.shootTimer = 1; enemy.applySlow({ multiplier: .67, duration: 3 }); enemy.applySlow({ multiplier: .67, duration: 3 }); enemy.update(1, { width: 480 }); assert(Math.abs(enemy.age - .67) < .001 && Math.abs(enemy.y - 67) < .001 && Math.abs(enemy.slowTimer - 2) < .001, "ice shard slow did not reduce all enemy behavior speed"); });
test("ice shard collision applies two damage and slow", () => { const definition = { id: "test-ice", type: "striker", hp: 100, speed: 100, radius: 8, score: 1, shootInterval: 2 }; const enemy = new Enemy(definition, 100, { spawnY: 100 }); const projectile = new Projectile({ x: 100, y: 100, vx: 0, vy: -1, damage: 2, radius: 4, color: "#a5f6ec", life: 1, team: "player", kind: "frostNeedle", pierce: true, slow: { multiplier: .67, duration: 3 } }); const result = new CollisionSystem().resolve({ player: { x: 300, y: 500, radius: 10 }, enemies: [enemy], projectiles: [projectile] }); assert(enemy.hp === 98 && enemy.slowTimer === 3 && result.destroyedEnemies.size === 0, "ice shard collision effect is incorrect"); });
