test("enemy contact damages player but never destroys the enemy", () => { const player = { x: 100, y: 100, radius: 12 }; const enemy = { id: "contact", x: 100, y: 100, radius: 12, hp: 5, definition: { score: 10 } }; const result = new CollisionSystem().resolve({ player, enemies: [enemy], projectiles: [] }); assert(result.playerDamage === GAME_CONFIG.projectile.enemyContactDamage, "contact damage missing"); assert(!result.destroyedEnemies.has(enemy) && enemy.hp === 5, "contact collision destroyed or damaged the enemy"); });
