test("fusion definitions keep independent mechanics while disabled modules stay out of player loadouts", () => { const ids = ["fusion-abyss-bloom", "fusion-photon-chorus", "fusion-cryo-hive", "fusion-overflow-drive"]; const skills = ids.map((id) => getModuleById(id)?.skill?.id); assert(new Set(skills).size === ids.length && !skills.some((id) => ["sonicWave", "freeze", "decoy", "ionSaw", "overclock"].includes(id)), "fusion modules still reuse legacy active skills"); assert(ids.every((id) => getModuleById(id)?.beyondFusionOnly && getModuleById(id)?.fusionRecipe?.length), "fusion recipe metadata is missing"); const anchor = getModuleById("fusion-mirage-anchor"); const thunder = getModuleById("fusion-polar-saw"); const baseLightning = getModuleById("weapon-lightning-generator"); const abyss = getModuleById("fusion-abyss-bloom"); const system = new BeyondLightConeSystem(); assert(anchor.name === "时空锚点" && PLAYER_DISABLED_MODULE_IDS.has(anchor.id) && !MODULE_CONFIG.specials.includes(anchor) && !system.getBeyondRewardModules().some((module) => module.id === anchor.id), "时空锚点 should remain defined but disabled for players"); assert(getModuleById("fusion-overflow-drive") && PLAYER_DISABLED_MODULE_IDS.has("fusion-overflow-drive") && !MODULE_CONFIG.specials.includes(getModuleById("fusion-overflow-drive")) && !system.getBeyondRewardModules().some((module) => module.id === "fusion-overflow-drive"), "溢流驱动 should remain defined but disabled for players"); assert(thunder.name === "惊雷" && thunder.type === "weapon" && !thunder.skill && MODULE_CONFIG.weapons.includes(thunder) && thunder.behavior?.type === "lightning" && thunder.behavior.fireInterval < baseLightning.behavior.fireInterval && thunder.behavior.projectile.damage > baseLightning.behavior.projectile.damage && thunder.footprint.cells.length === 4 && thunder.fusionRecipe.length === 2 && thunder.fusionRecipe.every((item) => item.moduleId === "weapon-lightning-generator" && item.y === 1), "惊雷 automatic lightning configuration"); assert(abyss.skill?.id === "abyssBloom" && abyss.type === "special" && abyss.behavior === undefined, "深渊花冠 still uses its independent active mechanic"); });
test("overclock refreshes without stacking", () => { const game = Object.create(Game.prototype); game.player = { overclockTimer: 1 }; game.startOverclock(5); assert(game.player.overclockTimer === 5, "overclock did not refresh to five seconds"); game.startOverclock(5); assert(game.player.overclockTimer === 5, "repeated overclock changed the duration or stacked it"); const player = { x: 240, y: 700, stats: { attackSpeed: 1 }, overclockTimer: 5, loadout: createLoadout({ modules: [{ moduleId: "weapon-nest", x: 4, y: 3 }, { moduleId: "special-overclock", x: 3, y: 3 }, { moduleId: "special-overclock", x: 5, y: 3 }] }), canFireWeapon: () => true, armWeapon(_id, interval) { this.interval = interval; } }; new WeaponSystem().firePlayer(player, []); assert(Math.abs(player.interval - 6 / 1.8) < 0.001, "multiple overclock modules stacked their attack speed"); });
test("black hole captures bullets and detonates their damage", () => { const player = { x: 240, y: 700, loadout: createLoadout({ modules: [{ moduleId: "weapon-black-hole", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {} }; const hole = new WeaponSystem().firePlayer(player, [])[0]; const enemyBolt = new Projectile({ x: hole.x + 40, y: hole.y, vx: 0, vy: 80, damage: 6, radius: 4, color: "#ff557c", life: 3, team: "enemy" }); const game = Object.create(Game.prototype); game.projectiles = [hole, enemyBolt]; game.enemies = []; game.applyBlackHolePull(0.1); assert(enemyBolt.blackHoleCapturedBy === hole && hole.blackHole.capturedProjectiles.has(enemyBolt) && enemyBolt.blackHoleOrbit.radius > 0 && enemyBolt.blackHoleOrbit.radius < hole.blackHole.pullRadius && !hole.blackHole.slowed, "black hole capture orbit state"); const enemy = { id: "detonation-target", x: hole.x, y: hole.y, radius: 10, hp: 20, definition: { score: 1 }, takeDamage(amount) { this.hp -= amount; return false; } }; hole.life = 0; const result = new CollisionSystem().resolve({ player, enemies: [enemy], projectiles: [hole, enemyBolt] }); assert(enemy.hp === 14 && result.removedProjectiles.has(enemyBolt) && result.explosionEvents[0].kind === "blackHole" && result.explosionEvents[0].capturedCount === 1, "captured bullet did not detonate"); });
test("black hole detonates one second after capturing an enemy", () => { const player = { x: 240, y: 700, loadout: createLoadout({ modules: [{ moduleId: "weapon-black-hole", x: 4, y: 3 }] }), canFireWeapon: () => true, armWeapon: () => {} }; const hole = new WeaponSystem().firePlayer(player, [])[0]; const enemy = { id: "captured-enemy", x: hole.x, y: hole.y + 20, hp: 10 }; const game = Object.create(Game.prototype); game.projectiles = [hole]; game.enemies = [enemy]; game.applyBlackHolePull(0.1); assert(hole.blackHole.enemyCaptured && Math.abs(hole.blackHole.detonationTimer - 0.9) < 0.001, "enemy capture did not start one-second detonation timer"); game.applyBlackHolePull(0.9); assert(hole.life <= 0, "black hole did not detonate after one second"); });
test("flame crossbow spreads and applies nine burn ticks", () => { const loadout = createLoadout({ modules: [{ moduleId: "weapon-flame-crossbow", x: 4, y: 3 }] }); const player = { x: 240, y: 700, stats: { attackSpeed: 1 }, loadout, canFireWeapon: () => true, armWeapon: () => {} }; const shots = new WeaponSystem().firePlayer(player, []); const guardian = ENEMY_CONFIG.find((enemy) => enemy.type === "guardian") ?? ENEMY_CONFIG.at(-1); const target = new Enemy(guardian, 240, { spawnY: 200 }); shots[1].x = target.x; shots[1].y = target.y; const result = new CollisionSystem().resolve({ player, enemies: [target], projectiles: shots }); const ticks = [...Array(3)].flatMap(() => target.updateBurn(1)); assert(shots.length === 3 && shots.every((shot) => shot.kind === "flameArrow") && result.damageEvents.some((event) => event.amount === 5 && event.element === "fire") && ticks.length === 9 && ticks.every((event) => event.amount === 1 && event.element === "fire"), "flame crossbow spread or burn failed"); });
test("water shot disappears and deals splash damage", () => { const loadout = createLoadout({ modules: [{ moduleId: "weapon-water-shot", x: 4, y: 3 }] }); const player = { x: 240, y: 700, stats: { attackSpeed: 1 }, loadout, canFireWeapon: () => true, armWeapon: () => {} }; const shots = new WeaponSystem().firePlayer(player, []); const guardian = ENEMY_CONFIG.find((enemy) => enemy.type === "guardian") ?? ENEMY_CONFIG.at(-1); const target = new Enemy(guardian, 240, { spawnY: 200 }); const nearby = new Enemy(guardian, 260, { spawnY: 200 }); shots[0].x = target.x; shots[0].y = target.y; const result = new CollisionSystem().resolve({ player, enemies: [target, nearby], projectiles: shots }); assert(shots[0].kind === "waterShot" && result.removedProjectiles.has(shots[0]) && target.hp === target.maxHp - 3 && nearby.hp === nearby.maxHp - 2 && result.damageEvents.some((event) => event.amount === 2 && event.element === "water"), "water splash behavior failed"); });
